class FxVerdictTests(unittest.TestCase):
    def test_the_real_pass_transcript_passes(self):
        report = verdict(REAL_FX_PASS_TRANSCRIPT, reached=True)
        self.assertEqual(report["problems"], [])
        self.assertEqual(report["verdict"], "PASS")

    def test_a_flat_write_compare_only_run_names_exactly_what_it_lacks(self):
        self.assertEqual(missing_assertions(REAL_FLAT_EXTENDED_SESSION), [
            "path-structured netboot fetch",
            "butterfly scan started",
            "zero-error ledger after each exercise (1 of 2)",
        ])
        report = verdict(REAL_FLAT_EXTENDED_SESSION, reached=True)
        self.assertEqual(report["verdict"], "FAIL")

    def test_no_real_clean_run_carries_a_failure_marker(self):
        self.assertEqual(failure_markers_present(REAL_FX_PASS_TRANSCRIPT), [])
        self.assertEqual(failure_markers_present(REAL_FLAT_EXTENDED_SESSION), [])

    def test_the_mis_driven_session_carries_its_real_open_failure(self):
        # The same shifted answers first opened controller 1, which has
        # no disk: fx's "Failed to open" is a real marker in that run.
        self.assertEqual(failure_markers_present(REAL_UNANSWERED_PROMPT),
                         ["Failed to open"])

    def test_an_unanswered_prompt_never_reaches_a_ledger(self):
        missing = missing_assertions(REAL_UNANSWERED_PROMPT)
        self.assertIn("write-compare scan started", missing)
        self.assertIn("butterfly scan started", missing)
        self.assertIn("zero-error ledger after each exercise (0 of 2)", missing)
        report = verdict(REAL_UNANSWERED_PROMPT, reached=False)
        self.assertEqual(report["verdict"], "FAIL")


if __name__ == "__main__":
    unittest.main()
